SELECT *
FROM audit_event_read_model


        AND (
            actor_id LIKE CONCAT('%', #{keyword}, '%')
            OR action LIKE CONCAT('%', #{keyword}, '%')
            OR resource_id LIKE CONCAT('%', #{keyword}, '%')
            OR client_ip LIKE CONCAT('%', #{keyword}, '%')
        )


        AND level = #{level}


        AND source_service = #{sourceService}


        AND actor_id = #{actorId}


        AND occurred_at >= #{startDate}


        AND occurred_at <= #{endDate}


ORDER BY occurred_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM audit_event_read_model


